"""A product introduction and an explicitly graded public interview evidence register."""
import json
from build_final_project_workshop import icon


def build_intro(root, twin, p, ul):
    evidence = json.loads((root/'final-project/interview-evidence.json').read_text())
    def link(href, fa, en):
        return f'<a class="workshop-link" href="{href}">'+twin(fa,en)+icon('next')+'</a>'

    definition = '<div class="project-definition"><div><h3>'+twin('زیرساخت مشترک برای برنامه‌های AI یک تیم','Shared infrastructure for a team’s AI apps')+'</h3>'+p('توسعه‌دهنده برنامه‌اش رو با مدل، prompt، ابزارهای مجاز و دادهٔ موردنیاز تعریف می‌کنه. پلتفرم قراره اجراش رو بپذیره، وضعیتش رو نگه داره، مدل و ابزار رو صدا بزنه و نتیجه و trace قابل‌بررسی برگردونه.','A developer defines their app with its model, prompt, permitted tools, and data. The platform takes the run, keeps its state, calls the model and the tools, and hands back a result and a trace you can actually read.')+'<dl class="project-contract">'+''.join('<div><dt>'+twin(*name)+'</dt><dd>'+twin(*value)+'</dd></div>' for name,value in [
        (('کاربر اصلی','Primary user'),('توسعه‌دهندهٔ برنامهٔ AI','AI-application developer')),
        (('ورودی','Input'),('تعریف app، داده و درخواستِ اجرا','App definition, data, and a run request')),
        (('خروجی','Output'),('نتیجه، وضعیت، شواهد و trace هر run','Result, status, evidence, and a per-run trace')),
    ])+'</dl></div><div class="project-demo"><h3>'+twin('دموی پیشنهادی: چرا API کند شده؟','Proposed demo: why did the API slow down?')+'</h3>'+p('فرض کن یه alert وارد شد. برنامهٔ Investigator از طریق پلتفرم، deployment اخیر، metric، trace و runbook مجاز رو می‌خونه.','Picture this: an alert comes in. Through the platform, the Investigator app reads recent deployments, metrics, traces, and an authorized runbook.')+'<div class="demo-evidence" aria-label="Proposed evidence sources">'+''.join('<bdi>'+x+'</bdi>' for x in ['Deployments','Metrics','Traces','Runbooks'])+'</div><h4>'+twin('گزارشی که می‌خواهیم بگیریم','The report we want to receive')+'</h4>'+ul([('چه اتفاقی افتاد و به چه ترتیبی؟','What happened, and in what order?'),('کدام فرضیه با کدام شاهد جور درمیاد؟','Which hypothesis fits which piece of evidence?'),('چه چیزی هنوز نامعلوم است؟','What remains uncertain?')])+p('سناریوی آزمایشگاه مصنوعیه. هم «نتیجهٔ مستند» درسته، هم «شواهد کافی نیست» — هر دو خروجی درست حساب می‌شن.','The lab scenario is synthetic. Both “a documented result” and “insufficient evidence” count as correct answers.')+'</div></div>'
    problems = [
        ('Model Gateway','layer-4','هر app جدا از بقیه، اتصال مدل، credential و هزینه رو خودش مدیریت می‌کنه.','Every app manages its model connection, credentials, and spend all on its own.','یک مرز مشترک که توش انتخاب مدل، مجوز، deadline، budget و ثبت مصرف انجام می‌شه.','One shared boundary where routing, authorization, deadlines, budgets, and usage get recorded.'),
        ('Durable Runtime','layer-1','با crash یا timeout، اجرای چندمرحله‌ای نیمه‌کاره راه می‌مونه.','A crash or a timeout leaves a multi-step run half-finished.','وضعیت و نتیجهٔ stepها باید پایدار بمونه؛ retry و ادامهٔ اجرا هم قرارداد روشن داشته باشه.','Step state and results have to stay durable, and retry and resume need explicit contracts.'),
        ('Live Context','layer-0','داده عوض یا حذف می‌شه و ممکنه مجوزهای قبلی دیگه معتبر نباشن.','Data changes or gets deleted, and yesterday\'s permissions may no longer hold.','بازیابی دادهٔ نسخه‌دار و مجاز؛ تازگی و CDC بر اساس نیاز و آزمون تصمیم گرفته می‌شن.','Retrieve versioned, authorized data; freshness and CDC get decided by requirements and tests.'),
        ('Evaluation & Release','layer-3','با تغییر prompt یا مدل، معلوم نیست کدوم رفتار بهتر شد و کدوم خراب‌تر.','Change the prompt or the model and nobody knows which behavior got better and which got worse.','نسخه‌های ثابت، dataset و آزمونِ کیفیت؛ و تصمیمِ انتشار بر اساس شاهد.','Pinned versions, datasets, and quality tests; the release decision rests on evidence.'),
        ('AI Investigator','layer-2','برای بررسی رخداد باید شواهدِ چند منبع رو کنار هم گذاشت.','Investigating an incident means putting evidence from several sources side by side.','یک app نمونه که از قابلیت‌های مشترک استفاده می‌کنه؛ بعداً app پاسخ‌گویی مستند هم همین هسته رو به کار می‌گیره.','A sample app that rides the shared capabilities; a cited-answer app uses the same core later.'),
    ]
    capabilities = '<div class="project-problems"><h3>'+twin('چه مشکلی را حل می‌کنیم؟','Which problems are we solving?')+'</h3>'
    for name,color,problem_fa,problem_en,solution_fa,solution_en in problems:
        capabilities += '<article class="problem-row"><h4 class="'+color+'" lang="en" dir="ltr">'+name+'</h4><div><h5>'+twin('مسئله','Problem')+'</h5>'+p(problem_fa,problem_en)+'</div><div><h5>'+twin('مسئولیت پیشنهادی','Proposed responsibility')+'</h5>'+p(solution_fa,solution_en)+'</div></article>'
    capabilities += '</div>'
    scope = '<div class="project-scope"><div><h3>'+twin('اولین چیزی که می‌سازیم','The first thing to build')+'</h3>'+p('پیشنهاد ADR-002: یه مسیر کوچک از ثبت app و ارسال run تا یه فراخوانی مدل، یه ابزار خواندنی و گرفتن نتیجه و trace. همین مسیر باید قابل‌اجرا و قابل‌آزمون زیر crash باشه.','ADR-002 proposes one small path: register an app, submit a run, call one model and one read-only tool, and get the result and trace back. That path has to be runnable and crash-testable.')+link('#ADR-002','مرز نسخهٔ اول هنوز پیشنهادی است','The first-version boundary remains proposed')+'</div><div><h3>'+twin('چیزی که بعداً اضافه می‌کنیم','What comes later')+'</h3>'+p('بعداً می‌رسیم به: context زنده و CDC، ارزیابی و انتشار نسخه‌ها، چند برنامه روی هستهٔ مشترک و آزمایش serving روی GPU. فعلاً از مدلِ آماده استفاده می‌کنیم؛ آموزش یه مدل بنیادی از صفر توی این scope نیست.','Later comes live context and CDC, evaluation and release, several apps on the shared core, and GPU serving experiments. For now we use an off-the-shelf model; training a foundation model from scratch is out of scope here.')+link('#roadmap','مسیر پیشنهادی ساخت','The proposed build track')+'</div></div>'
    careers = '<div class="project-careers"><h3>'+twin('چه چیزی برای رزومه قابل‌نشان‌دادن می‌شود؟','What would become portfolio evidence?')+'</h3>'+p('برای مسیر AI Engineer: طراحی ابزار و retrieval، ارزیابی پاسخ و تحلیل خطا. برای AI Platform Engineer: قرارداد API، دوام اجرا، کنترل دسترسی، ظرفیت، هزینه و observability. مدرکِ کار می‌شه: مخزن اجرایی، demo، آزمون crash، نتیجهٔ eval و ADRها. فعلاً این صفحه دفترِ طراحیِ همون کاره.','For the AI Engineer path: tool and retrieval design, output evaluation, and error analysis. For the AI Platform Engineer path: API contracts, durable execution, access control, capacity, cost, and observability. The evidence is a working repo, a demo, crash tests, eval results, and ADRs. Right now this page is the design workbook for that work.')+'</div>'
    overview = '<section id="overview" class="workshop-section project-overview"><h2>'+twin('این پروژه دقیقاً چیست؟','What exactly is this project?')+'</h2>'+p('قضیه اینه که: یه پلتفرم قابل‌استفادهٔ مجدد می‌سازیم که توسعه‌دهندهٔ برنامهٔ AI خودش رو روش اجرا و بررسی کنه. Investigator اولین برنامهٔ نمونه است؛ هستهٔ پروژه زیرساختیه که برنامه‌های دیگه هم بتونن ازش استفاده کنن.','Here\'s the thing: we\'re building a reusable platform where a developer runs and inspects their own AI app. Investigator is the first sample app; the core is infrastructure other apps can lean on too.')+definition+capabilities+scope+careers+'<div class="workshop-links">'+link('#company-evidence','این مسئله‌ها کجا مطرح شده‌اند؟','Where have these problems appeared?')+link('#start-here','حالا طراحی را شروع کنیم','Start the design workshop')+'</div></section>'

    industry = '<div class="industry-evidence"><h3>'+twin('نمونه‌های مستند در کارِ واقعی شرکت‌ها','Documented industry examples')+'</h3>'+p('این مقاله‌ها نشون می‌دن مسئلهٔ مهندسی واقعیه؛ ولی مدرکِ سؤال مصاحبه نیستن. ارتباطشون با پروژهٔ ما، برداشت خودمونه.','These articles show that the engineering problem is real; they aren\'t interview-prompt evidence, and their link to our project is our own reading.')
    for source in evidence['industry_sources']:
        industry += '<article><h4 lang="en" dir="ltr">'+source['company']+'</h4><div>'+p(*source['topic'])+f'<a href="{source["url"]}" target="_blank" rel="noopener">'+source['title']+'</a><span class="source-date" dir="ltr">'+source['date']+'</span></div></article>'
    industry += '</div>'
    register = '<div class="interview-register"><h3>'+twin('سؤال‌ها و بحث‌های گزارش‌شده در مصاحبه','Reported interview questions and discussions')+'</h3>'+p('۸ رکورد از ۷ شرکت: یک تمرین رسمیِ منتشرشده و هفت روایت داوطلب. عنوان‌ها خلاصه‌سازی شده‌ان، نه نقلِ کامل صورت‌سؤال. هر رکورد بهت می‌گه نقش چی بوده، چه تاریخی داریم، منبعش کجاست و تا چه حد به پروژهٔ ما می‌خوره.','Eight records across seven companies: one officially released exercise plus seven candidate accounts. The titles are paraphrases, not full prompt reproductions. Every record tells you the role, the date we have, the source, and how far it reaches into our project.')
    for row in evidence['reports']:
        official = row['kind']=='official'
        label = twin('انتشار رسمی' if official else 'روایت داوطلب','Official release' if official else 'Candidate report')
        register += f'<details class="interview-record" id="{row["id"]}" data-evidence="{row["kind"]}"><summary><span class="interview-company"><bdi>'+row['company']+'</bdi><span>'+row['role']+'</span><span class="interview-question-preview">'+twin(*row['short_title'])+'</span></span><span class="evidence-kind">'+label+'</span>'+icon('plus')+'</summary><div class="interview-body"><h4>'+twin('چه چیزی گزارش شده؟','What was reported?')+'</h4>'+p(*row['question'])+'<h4>'+twin('کجای پروژه به آن مربوط است؟','Where does it connect to this project?')+'</h4>'+p(*row['mapping'])+'<p class="interview-topic-links">'+''.join(f'<a href="#{target}">{target}</a>' for target in row['anchors'])+'</p><div class="evidence-limits">'+p(*row['date_note'])+p(*row['limit'])+'</div><a class="workshop-link" href="'+row['url']+'" target="_blank" rel="noopener">'+twin('باز کردن منبع: ','Open source: ')+row['source']+icon('next')+'</a></div></details>'
    register += '</div>'
    methodology = '<details class="workbook-reference"><summary>'+twin('روش جست‌وجو و حدودِ اعتبار این فهرست','Search method and limits of this register')+icon('plus')+'</summary><div class="disclosure-body">'+p('در ۱۵ اکتبر ۲۰۲۶ یه جست‌وجوی گسترده زدیم: ۲۶ عبارتِ هدفمند در منابع عمومی، Reddit، LeetCode، تجربه‌های Aced/Exponent و Taro، و وبلاگ‌های مهندسی. این نه فهرست جامعِ کل اینترنته، نه بانکِ تأییدشدهٔ سؤال‌های شرکت‌ها.','On 15 October 2026 we ran a broad search: 26 targeted queries across public sources, Reddit, LeetCode, Aced/Exponent and Taro accounts, and engineering blogs. It\'s neither the complete internet nor a verified company question bank.')+p('تاریخ بررسی با تاریخ مصاحبه فرق داره، پس هرجا تاریخ دقیق نداریم، نوشته‌ایم. چند بازنشر از یه روایت، شاهد مستقل حساب نمی‌شه. پست‌های تبلیغاتی و فهرست‌های بدون منبع هم در نتیجهٔ رسمی نمی‌رن؛ و دو روایتِ با زمینهٔ تبلیغاتی دقیقاً با همون محدودیت علامت خوردن.','The review date and the interview date are different things, so wherever we lack an exact date we say so. A few reposts of one story don\'t count as independent corroboration. Promotional posts and unsourced banks stay out of the official tier, and the two reports with a promotional context are flagged with exactly that limit.')+p('برای سؤالِ «همین پلتفرم کامل رو طراحی کن»، شاهد عمومیِ کافی پیدا نشد. این پروژه یه ترکیب آموزشیه؛ شباهتِ هر تکه به یه سؤال، یعنی scope یکیه یا قبول می‌شی؟ نه — این رو نباید خوند.','For the prompt “design this exact complete platform,” we found no sufficient public evidence. This project is an educational synthesis, and a part resembling one question doesn\'t mean the scope matches or that it gets you hired.')+'<p><a href="interview-evidence.json">'+twin('فهرست منابع و وضعیت شواهد (JSON)','Sources and evidence status (JSON)')+'</a></p></div></details>'
    companies = '<section id="company-evidence" class="workshop-section company-evidence"><h2>'+twin('در کدام شرکت‌ها چنین مسئله‌هایی مطرح شده؟','Which companies have raised related problems?')+'</h2>'+p('راستش، خودِ این پروژه رو به یک شرکت نسبت نمی‌دهیم. پایین، نمونهٔ رسمیِ کار مهندسی، تمرینِ منتشرشده و تجربهٔ گزارش‌شدهٔ مصاحبه برچسب جدا دارن. تاریخ بررسی منابع: ۱۵ اکتبر ۲۰۲۶.','Honestly, we don\'t attribute this project to any one company. Below, official engineering work, a released exercise, and reported interview experiences each carry their own label. Sources checked on 15 October 2026.')+register+industry+methodology+'<div class="workshop-links">'+link('#start-here','از شناخت پروژه به طراحی نیازها','Move from project context to requirements')+'</div></section>'
    return overview+companies
